// spec: specs/picking.md §7 · кейсы .qa/tests/picking/pick-15-shortage-order-card-text.md, pick-16-shortage-deliver-confirm.md
// seed: tests/seed.admin.spec.ts (+ worker через «כניסה כעובד» в отдельном окне, rep — rep.json)
// #fd2f41 (עבר QA 21.10): заказ, собранный с «חסר», — в «ליקוט במחסן» тег «לוקטה · חוסר אחד» и текст
//   «ההזמנה לוקטה עם חוסרים ואינה מסופקת במלואה — יש להחליט מה נשלח ללקוח.», без «כל הפריטים לוקטו במלואם» (admin и rep);
//   заказ без нехватки — «כל הפריטים לוקטו במלואם.». «סמן כסופק» у admin на заказе с нехваткой → окно «ההזמנה לוקטה בחוסר» /
//   «מוצר אחד לא לוקט במלואו. לסמן את ההזמנה כסופקה בכל זאת?»: «ביטול» — статус не меняется, подтверждение — «סופקה».
//   Без нехватки — окна нет. Экран водителя — вне объёма (решение пользователя 21.10).
// Нехватка создаётся без «עריכה» сверх остатка (решение 20.10: сверх остатка должно блокироваться, #6a98bd в реджекте):
//   товар QA-AUTO-fd2f-<ts> на свободной полке X (шкаф F/E, не G), приёмка 3 → заказы test A (2 шт.) и B (1 шт.) утверждены →
//   «החזרה לספק» 1 шт. из X (X=2) → работник собирает B полностью (X=1), A — «חסר» (взято 1 из 2).
// ⚠️ НЕОБРАТИМО: 2 заказа test (₪1/шт.) доводятся до «סופקה», журнал (קליטה, החזרה לספק, ליקוט) неудаляем.
// ליקוט — admin.json в ОТДЕЛЬНОМ окне → «כניסה כעובד» → «עובד מחסן בדיקה»; сессия окна не сохраняется в auth.
// Корзина buyer общая → @orders @data, serial; не параллельно с cart-checkout / order-lifecycle / picking-*.
// afterAll: «ממתינה לאישור» — отклонить, утверждённые — довести до «סופקה» (с подтверждением окна), корзина пуста, товар удалён, X «ריק».
import { test, expect, Page, Browser } from '@playwright/test';
import * as H from '../inventory/_places';
import { impersonate, backToAdmin } from '../warehouse-map/_helpers';
import { placeOrder, emptyCart } from '../orders/_qa-order';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const WORKER = 'עובד מחסן בדיקה';
const P = `QA-AUTO-fd2f-${TS}`;
const created = new Set<string>();
const used: H.Used = new Map();
type Order = { no: string; url: string; id: string };
const state: { X?: H.Place; id?: string; A?: Order; B?: Order } = {};

const SHORT_TEXT = 'ההזמנה לוקטה עם חוסרים ואינה מסופקת במלואה — יש להחליט מה נשלח ללקוח.';
const FULL_TEXT = 'כל הפריטים לוקטו במלואם.';
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');
const pickingCard = (page: Page) =>
  page.getByRole('heading', { level: 3, name: 'ליקוט במחסן' }).locator('xpath=ancestor::*[.//*[contains(normalize-space(), "לוקטה")]][1]');

async function openOrderById(page: Page, o: Order) {
  await page.goto(o.url);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
}

async function openOrderByNo(page: Page, no: string) {
  await page.goto('/orders');
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await page.getByRole('button', { name: new RegExp(`^#${no} `) }).click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
}

async function approve(page: Page, no: string): Promise<Order> {
  await openOrderByNo(page, no);
  await page.getByRole('button', { name: 'אישור הזמנה' }).click();
  const dlg = page.getByRole('dialog');
  await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
  await expect(header(page)).toContainText(/אושרה/, { timeout: 20_000 });
  const url = page.url();
  return { no, url, id: url.match(/orders\/([0-9a-f-]{36})/)![1] };
}

/** «החזרות» → «החזרה לספק» 1 шт. из полки X. */
async function returnOneFromPlace(page: Page, avail: number) {
  const X = state.X!;
  await H.openMap(page);
  await page.getByRole('button', { name: 'החזרות' }).click();
  await page.getByRole('menuitem', { name: /^החזרה לספק/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'החזרה לספק' })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'חיפוש פריט' }).fill(P);
  const box = dlg.getByRole('checkbox', { name: new RegExp(`^${P} · \\S+ זמין ${avail} · מדף ${X.code}`) });
  await box.check();
  await box.locator('xpath=ancestor::label[1]/parent::*').getByRole('spinbutton', { name: `כמות ל${P}` }).fill('1');
  await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(`QA-AUTO-fd2f-${TS}`);
  const resp = page.waitForResponse((r) => r.url().includes('/rpc/return_to_supplier') && r.request().method() === 'POST');
  await dlg.getByRole('button', { name: 'רישום ההחזרה' }).click();
  expect((await resp).status()).toBe(200);
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

const station = (page: Page) => page.getByRole('listitem').filter({ hasText: P });

/** Работник (отдельное окно, вход админом → «כניסה כעובד»): собрать заказ; shortage — «חסר» вместо «לוקט». */
async function pick(browser: Browser, o: Order, shortage: boolean) {
  const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
  const page = await ctx.newPage();
  try {
    await impersonate(page, WORKER);
    await page.goto(`/warehouse/picking?order=${o.id}`);
    await expect(page.getByRole('heading', { level: 2, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('button', { name: 'התחלת ליקוט', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'רשימת ליקוט' })).toBeVisible({ timeout: 30_000 });
    const st = station(page);
    await expect(st).toContainText(state.X!.code);
    if (!shortage) {
      await st.getByRole('button', { name: 'לוקט', exact: true }).click();
    } else {
      await st.getByRole('button', { name: 'חסר', exact: true }).click();
      // форма в станции: «כמה נלקטו בפועל? מתוך 2» → 1 → «אישור חוסר»
      await expect(st.getByText(/נרשמו 1 מתוך 2/)).toBeVisible();
      await st.getByRole('spinbutton', { name: 'כמה נלקטו בפועל?' }).fill('1');
      await st.getByRole('button', { name: 'אישור חוסר' }).click();
    }
    await expect(page.getByText('1/1', { exact: true })).toBeVisible({ timeout: 15_000 });
    await page.getByRole('button', { name: 'סיום ליקוט' }).click();
    await expect(page.getByText(/הליקוט הושלם/)).toBeVisible({ timeout: 20_000 });
    await backToAdmin(page);
  } finally {
    await ctx.close(); // сессия окна не сохраняется
  }
}

/** Уборка: довести сборку хвоста до конца — «לוקט», а если недоступен — «חסר» со взятым количеством. */
async function pickAny(browser: Browser, o: Order) {
  const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
  const page = await ctx.newPage();
  try {
    await impersonate(page, WORKER);
    await page.goto(`/warehouse/picking?order=${o.id}`);
    await expect(page.getByRole('heading', { level: 2, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('button', { name: 'התחלת ליקוט', exact: true }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'רשימת ליקוט' })).toBeVisible({ timeout: 30_000 });
    const st = station(page);
    const picked = st.getByRole('button', { name: 'לוקט', exact: true });
    if (await picked.isEnabled()) await picked.click();
    else {
      await st.getByRole('button', { name: 'חסר', exact: true }).click();
      const all = st.getByRole('button', { name: /^נלקטו כל/ });
      if (await all.count()) await all.click();
      else await st.getByRole('spinbutton', { name: 'כמה נלקטו בפועל?' }).fill('0');
      await st.getByRole('button', { name: 'אישור חוסר' }).click();
    }
    await expect(page.getByRole('button', { name: 'סיום ליקוט' })).toBeEnabled({ timeout: 15_000 });
    await page.getByRole('button', { name: 'סיום ליקוט' }).click();
    await expect(page.getByText(/הליקוט הושלם/)).toBeVisible({ timeout: 20_000 });
    await backToAdmin(page);
  } finally {
    await ctx.close();
  }
}

async function expectShortageCard(page: Page) {
  const card = pickingCard(page);
  await expect(card).toContainText('לוקטה · חוסר אחד', { timeout: 30_000 });
  await expect(card.getByText(SHORT_TEXT, { exact: true })).toBeVisible();
  await expect(page.getByText(FULL_TEXT)).toHaveCount(0);
}

async function expectFullCard(page: Page) {
  await expect(page.getByText(FULL_TEXT, { exact: true })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(SHORT_TEXT)).toHaveCount(0);
  await expect(pickingCard(page)).not.toContainText('חוסר');
}

const shortDialog = (page: Page) => page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'ההזמנה לוקטה בחוסר' }) });

/** Довести заказ до «סופקה»; confirm — подтверждать окно нехватки, если появится. */
async function deliver(page: Page, confirm: boolean) {
  for (const step of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח']) {
    const btn = page.getByRole('button', { name: step });
    if ((await btn.count()) && (await btn.isEnabled())) {
      await btn.click();
      await expect(btn).toHaveCount(0, { timeout: 20_000 });
    }
  }
  const done = page.getByRole('button', { name: 'סמן כסופקה' });
  if (!(await done.count())) return;
  await done.click();
  if (confirm && (await shortDialog(page).isVisible().catch(() => false))) {
    await shortDialog(page).getByRole('button', { name: 'סמן כסופקה' }).click();
  }
  await expect(header(page)).toContainText(/סופקה?/, { timeout: 20_000 });
}

test.describe('picking — הזמנה שלוקטה בחוסר: טקסט בכרטיס ואישור «סמן כסופק» (#fd2f41)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(400_000);
    const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
    const page = await ctx.newPage();
    try {
      for (const o of [state.A, state.B]) {
        if (!o) continue;
        try {
          await openOrderById(page, o);
          const reject = page.getByRole('button', { name: 'דחייה' });
          if (await reject.count()) {
            await reject.click();
            const dlg = page.getByRole('dialog');
            await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup #fd2f41');
            await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
            await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
          } else {
            if (await header(page).getByText(/ממתינה לליקוט|בליקוט/).count()) {
              await pickAny(browser, o);
              await openOrderById(page, o);
            }
            await deliver(page, true);
          }
        } catch (e) {
          test.info().annotations.push({ type: 'cleanup', description: `#${o.no}: ${(e as Error).message.split('\n')[0]}` });
        }
      }
    } finally {
      await ctx.close();
    }
    const bctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
    try { await emptyCart(await bctx.newPage()); } catch { /* корзина */ } finally { await bctx.close(); }
    await H.cleanup(browser, created, used);
  });

  test('הכנה: מוצר במדף (3), הזמנות A=2 ו-B=1 מאושרות, החזרה לספק 1 מהמדף; B לוקטה במלואה, A — «חסר» #fd2f41 @desktop @data @orders', async ({ page, browser }) => {
    test.setTimeout(600_000);
    const [X] = await H.pickEmptyPlaces(page, 1, ['F', 'E']);
    state.X = X;
    await H.createProduct(page, P, `QAFD2F${TS}`, created, '1');
    H.track(used, P, X);
    await H.bindPlace(page, P, X);
    await H.receive(page, P, 3, X.code);
    state.id = await H.productId(page, P);

    const bctx = await browser.newContext({ storageState: H.auth('buyer'), locale: 'he-IL', baseURL: test.info().project.use.baseURL });
    const buyer = await bctx.newPage();
    let noA: string, noB: string;
    try {
      noA = await placeOrder(buyer, [{ id: state.id, name: P, qty: 2 }], `QA-AUTO-fd2f-A-${TS}`);
      state.A = { no: noA, url: '', id: '' };
      noB = await placeOrder(buyer, [{ id: state.id, name: P, qty: 1 }], `QA-AUTO-fd2f-B-${TS}`);
      state.B = { no: noB, url: '', id: '' };
    } finally {
      await bctx.close();
    }
    state.A = await approve(page, noA);
    state.B = await approve(page, noB);

    await returnOneFromPlace(page, 3); // X: 3 → 2
    await pick(browser, state.B, false); // X: 2 → 1
    await pick(browser, state.A, true); // нужно 2, на полке 1 → «חסר»
  });

  test('admin: הזמנה בחוסר — «לוקטה · חוסר אחד» + טקסט החוסר, בלי «כל הפריטים לוקטו במלואם»; הזמנה מלאה — «כל הפריטים לוקטו במלואם.» #fd2f41 @desktop', async ({ page }) => {
    test.skip(!state.A || !state.B || !state.A.id, 'нет подготовленных заказов');
    await openOrderById(page, state.A!);
    await expect(header(page)).toContainText(/מוכנה? למשלוח/, { timeout: 20_000 });
    await expectShortageCard(page);
    await openOrderById(page, state.B!);
    await expectFullCard(page);
  });

  test('נציג (rep): אותו טקסט חוסר בהזמנה A ו«כל הפריטים לוקטו במלואם.» ב-B #fd2f41 @desktop', async ({ browser }) => {
    test.skip(!state.A || !state.B || !state.A.id, 'нет подготовленных заказов');
    const ctx = await browser.newContext({ storageState: H.auth('rep'), locale: 'he-IL', viewport: { width: 1440, height: 900 }, baseURL: test.info().project.use.baseURL });
    const page = await ctx.newPage();
    try {
      await openOrderById(page, state.A!);
      await expectShortageCard(page);
      await openOrderById(page, state.B!);
      await expectFullCard(page);
    } finally {
      await ctx.close();
    }
  });

  test('admin «סמן כסופק» בהזמנה בחוסר: חלון «ההזמנה לוקטה בחוסר»; «ביטול» — הסטטוס לא משתנה; אישור — «סופקה» #fd2f41 @desktop @data @orders', async ({ page }) => {
    test.skip(!state.A?.id, 'нет подготовленного заказа');
    await openOrderById(page, state.A!);
    await page.getByRole('button', { name: 'סמן כיצאה למשלוח' }).click();
    await expect(header(page)).toContainText('בדרך ללקוח', { timeout: 20_000 });

    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    const dlg = shortDialog(page);
    await expect(dlg).toBeVisible();
    await expect(dlg.getByText('מוצר אחד לא לוקט במלואו. לסמן את ההזמנה כסופקה בכל זאת?', { exact: true })).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(header(page)).toContainText('בדרך ללקוח');
    await page.reload();
    await expect(header(page)).toContainText('בדרך ללקוח', { timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'סמן כסופקה' })).toBeVisible();

    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(dlg).toBeVisible();
    await dlg.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(header(page)).toContainText('סופקה', { timeout: 20_000 });
    await expectShortageCard(page); // после поставки текст нехватки остаётся
  });

  test('admin «סמן כסופק» בהזמנה בלי חוסר — בלי חלון, ישר «סופקה» #fd2f41 @desktop @data @orders', async ({ page }) => {
    test.skip(!state.B?.id, 'нет подготовленного заказа');
    await openOrderById(page, state.B!);
    await page.getByRole('button', { name: 'סמן כיצאה למשלוח' }).click();
    await expect(header(page)).toContainText('בדרך ללקוח', { timeout: 20_000 });
    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(header(page)).toContainText('סופקה', { timeout: 20_000 });
    await expect(shortDialog(page)).toHaveCount(0);
    await expect(page.getByRole('dialog')).toHaveCount(0);
  });
});
